@media (max-width:959px){.ee-wa-flot{bottom:calc(84px + env(safe-area-inset-bottom))}}
/* Botón flotante de Instagram, justo encima del de WhatsApp */
.ee-ig-flot{--ig-base:16px;position:fixed;right:16px;bottom:calc(var(--ig-base) + 58px + env(safe-area-inset-bottom));z-index:60;display:grid;place-items:center;width:48px;height:48px;border-radius:999px;background:var(--crema-50);color:var(--rosa-700);border:1px solid var(--rosa-200);text-decoration:none;box-shadow:0 16px 30px -12px rgba(78,23,48,.45);transition:transform var(--dur-base) var(--ease-silk),background var(--dur-base) var(--ease-silk),color var(--dur-base) var(--ease-silk)}
.ee-ig-flot:hover{background:var(--rosa-600);color:var(--crema-50);transform:translateY(-2px)}
.ee-ig-flot:focus-visible{outline:2px solid var(--rosa-700);outline-offset:3px}
@media (max-width:959px){.ee-ig-flot{--ig-base:84px}}
@media (prefers-reduced-motion:reduce){.ee-ig-flot{transition:none}}
/* Pie: créditos en su propia línea, y espacio al final para que los botones flotantes no tapen el texto */
.ee-footer__credito{flex-basis:100%;text-align:center;opacity:.85}
.ee-footer{padding-bottom:calc(var(--sp-6) + 64px)}
@media (max-width:959px){.ee-footer{padding-bottom:calc(var(--sp-6) + 132px)}}
